using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from the external API for a given resource ID.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The resource identifier to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        yield return new ChatMessage(
            ChatRole.User,
            $"""
             Please summarize the following text in a {style} style.

             Text:
             {text}
             """);
    }
}

