using System.Reflection;

var asm = Assembly.LoadFrom(Environment.GetCommandLineArgs()[1]);

void Inspect(string typeName) {
    var t = asm.GetType(typeName);
    if (t == null) { Console.WriteLine($"NOT FOUND: {typeName}"); return; }
    Console.WriteLine($"\n=== {t.FullName} ===");
    foreach (var c in t.GetConstructors()) {
        var ps = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  ctor({ps})");
    }
    foreach (var p in t.GetProperties()) Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}

